var n=`0383-bitterballen`;var i=`world-0383`;var r=`NL`;var o=`western-europe`;var a=4;var l=163;var s={en:`Bitterballen`,ua:`Бітербален`};var u={en:`A traditional Netherlands dish made with ground beef, yellow onion, all-purpose flour, chicken egg. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Нідерланди. Основні інгредієнти: яловичий фарш, жовта цибуля, пшеничне борошно універсальне, куряче яйце. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`ground-beef`,450,`g`],[`yellow-onion`,150,`g`],[`unsalted-butter`,50,`g`]]},{en:`Make a rich beef ragout thickened with flour and stock; reduce until it can hold its shape after chilling.`,ua:`Приготуйте густе яловиче рагу з борошном і бульйоном, уваріть до консистенції, яка після охолодження тримає форму.`,t:[`roux-making`],m:8,i:[[`all-purpose-flour`,70,`g`],[`beef-stock`,370,`ml`],[`ground-nutmeg`,3,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 120 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 120 хвилин.`,t:[`rapid-chilling`],m:120,i:[]},{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:10,i:[[`chicken-egg`,2,`pcs`],[`breadcrumbs`,180,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 12 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 12 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:12,i:[[`sunflower-oil`,650,`ml`]]}];var g={slug:n,id:i,country:`NL`,region:o,servings:4,minutes:163,title:s,text:u,steps:d};export{r as country,g as default,i as id,l as minutes,o as region,a as servings,n as slug,d as steps,u as text,s as title};